 const string Source=SceneArchitectureBuilder.Source,Data=SceneArchitectureBuilder.Data,Folder=SceneArchitectureBuilder.Scenes;
 static RoomSceneCatalog catalog;static LifeWorldRules original,split;static Dictionary<string,string> objectRooms;static List<RoomPortalDefinition> links;static WorldInteractable[] templates;static TMPro.TMP_Text labelTemplate;
 static string FamilyObject(string id){if(new[]{"family-mother-bed","family-father-bed","family-closet","family-parent-side","family-parents-return"}.Contains(id))return "family-parents-bedroom";if(new[]{"family-bed","family-care","family-nursery-storage","family-nursery-side","family-ian-return"}.Contains(id))return "family-ian-bedroom";if(new[]{"family-basin","family-shower","family-toilet","family-bath-exit"}.Contains(id))return "family-bathroom";if(new[]{"family-fridge","family-cook","family-dishes","family-serve","family-player-seat","family-dine-1","family-dine-2","family-kitchen-return"}.Contains(id))return "family-kitchen";return "family-living";}
 static RoomSceneDefinition R(string id)=>catalog.Find(id);
 static WorldZoneDefinition Z(string id)=>split.Zone(id);
 static string RoomOf(WorldInteractable o)=>o.zone==FamilyLife.Home?FamilyObject(o.id):o.zone;
 static SceneId Id(string id){switch(id){case "home":return SceneId.RoomIndependentHome;case "bathroom":return SceneId.RoomIndependentBathroom;case "city":return SceneId.RoomCity;case "alley":return SceneId.RoomAlley;case "workplace":return SceneId.RoomWorkspace;case "office-bathroom":return SceneId.RoomWorkspaceBathroom;case "school":return SceneId.RoomSchool;case "shop":return SceneId.RoomShop;case "finance":return SceneId.RoomFinance;case "realestate":return SceneId.RoomRealEstate;case "residence":return SceneId.RoomResidence;case "family-living":return SceneId.RoomFamilyLiving;case "family-kitchen":return SceneId.RoomFamilyKitchen;case "family-parents-bedroom":return SceneId.RoomFamilyParents;case "family-ian-bedroom":return SceneId.RoomFamilyIan;default:return SceneId.RoomFamilyBathroom;}}
 static string Name(string id){switch(id){case "home":return "IndependentHome_Studio";case "bathroom":return "IndependentHome_Bathroom";case "city":return "City_Center";case "alley":return "ResidentialAlley";case "workplace":return "Workspace_Office";case "office-bathroom":return "Workspace_Bathroom";case "school":return "School_Classroom";case "shop":return "NeighborhoodShop";case "finance":return "StockMarket_Interior";case "realestate":return "RealEstate_Office";case "residence":return "Resident_Housing";case "family-living":return "FamilyHome_LivingRoom";case "family-kitchen":return "FamilyHome_Kitchen";case "family-parents-bedroom":return "FamilyHome_ParentsBedroom";case "family-ian-bedroom":return "FamilyHome_IanBedroom";default:return "FamilyHome_Bathroom";}}
 [MenuItem("Ian/Scene Architecture/Export Independent Rooms")]
 public static void Build(){if(Application.isPlaying)throw new Exception("Stop Play first");Directory.CreateDirectory(Data);Directory.CreateDirectory(Folder);Directory.CreateDirectory("Assets/_Game/Prefabs/SceneResidents");Directory.CreateDirectory("Docs/SceneArchitecture");ReadResidentialPlan();var scene=EditorSceneManager.OpenScene(Source);var w=UnityEngine.Object.FindAnyObjectByType<LifeWorldController>();original=AssetDatabase.LoadAssetAtPath<LifeWorldRules>("Assets/_Game/Data/Phase26/LifeWorldRules.asset");string rulePath=Data+"RoomWorldRules.asset";split=AssetDatabase.LoadAssetAtPath<LifeWorldRules>(rulePath);if(split!=null)EditorUtility.CopySerialized(original,split);else{split=UnityEngine.Object.Instantiate(original);AssetDatabase.CreateAsset(split,rulePath);}catalog=AssetDatabase.LoadAssetAtPath<RoomSceneCatalog>(Data+"RoomScenes.asset");if(catalog==null){catalog=ScriptableObject.CreateInstance<RoomSceneCatalog>();AssetDatabase.CreateAsset(catalog,Data+"RoomScenes.asset");}catalog.rules=split;
  var defs=new List<RoomSceneDefinition>();foreach(var zone in original.zones.Where(z=>z.id!=FamilyLife.Home&&z.id!=FamilyLife.Bath))defs.Add(new RoomSceneDefinition{roomId=zone.id,title=zone.title,sceneName=Name(zone.id),sceneId=Id(zone.id),legacyZone=zone.id,homeId=zone.id=="home"||zone.id=="bathroom"?"player":"",legacyBounds=new Rect(-zone.size/2,zone.size)});
  var plan=AssetDatabase.LoadAssetAtPath<FamilyHomeArchitecturePlan>("Assets/_Game/Data/Phase26/FamilyHomeArchitecture.asset");var map=new Dictionary<string,string>{{"parents","family-parents-bedroom"},{"ian","family-ian-bedroom"},{"bath","family-bathroom"},{"living","family-living"},{"kitchen","family-kitchen"}};
  foreach(var region in plan.rooms){string id=map[region.id];defs.Add(new RoomSceneDefinition{roomId=id,title=region.title,sceneName=Name(id),sceneId=Id(id),legacyZone=FamilyLife.Home,homeId="family",family=true,legacyBounds=region.floor,legacyOffset=region.floor.center});var zone=new WorldZoneDefinition{id=id,title=region.title,location=SceneId.Home,origin=original.Zone(FamilyLife.Home).origin+region.floor.center,size=region.floor.size,spawn=region.id=="ian"?new Vector2(0,-1.55f):new Vector2(0,-region.floor.height/2+1),walkableTop=region.floor.height/2,cameraSize=region.id=="living"?6.2f:region.floor.width>=12?5.5f:4.8f};var existing=Array.FindIndex(split.zones,z=>z.id==id);if(existing>=0)split.zones[existing]=zone;else split.zones=split.zones.Concat(new[]{zone}).ToArray();}
  foreach(var room in defs.Where(r=>r.family)){var layout=Layout(room.roomId);var zone=Z(room.roomId);zone.size=layout.size;zone.spawn=layout.spawn;zone.walkableTop=layout.size.y/2;zone.cameraSize=layout.cameraSize;}
  catalog.rooms=defs.ToArray();objectRooms=w.objects.Where(o=>o!=null&&o.kind!=WorldInteractionKind.NPC).GroupBy(o=>o.id).ToDictionary(g=>g.Key,g=>RoomOf(g.First()));objectRooms["family-bath-exit"]="family-bathroom";
  // Destination metadata is authored once; runtime never searches unloaded scene objects.
  links=new List<RoomPortalDefinition>();foreach(var o in w.objects.Where(o=>o.kind==WorldInteractionKind.Door&&!o.id.StartsWith("family-"))){var dest=catalog.Resolve(o.targetZone,o.arrival);if(dest==null)throw new Exception("Missing destination "+o.id);var reverse=w.objects.FirstOrDefault(x=>x.kind==WorldInteractionKind.Door&&x.zone==o.targetZone&&x.targetZone==o.zone);links.Add(new RoomPortalDefinition{doorId=o.id,sourceRoom=RoomOf(o),destinationRoom=dest.roomId,arrival=o.arrival-dest.legacyOffset,destinationEntryId=(reverse?.id??o.id)+"/arrival",facing=reverse?.GetComponent<WorldDoor>()==null?Vector2.down:-reverse.GetComponent<WorldDoor>().normal});}
  Add("family-front","alley","family-living",new Vector2(3.2f,-2.5f),Vector2.up,"family-exit");Add("family-exit","family-living","alley",new Vector2(2,2.5f),Vector2.down,"family-front");
  foreach(var p in new[]{new{Front="family-parents-door",Back="family-parents-return",Room="family-parents-bedroom",X=-4.5f},new{Front="family-ian-door",Back="family-ian-return",Room="family-ian-bedroom",X=-1.5f},new{Front="family-bath-front",Back="family-bath-exit",Room="family-bathroom",X=1.5f},new{Front="family-kitchen-front",Back="family-kitchen-return",Room="family-kitchen",X=4.5f}}){Add(p.Front,"family-living",p.Room,p.Room=="family-kitchen"?new Vector2(-4,-2.5f):new Vector2(0,-Z(p.Room).size.y/2+.95f),Vector2.up,p.Back);Add(p.Back,p.Room,"family-living",new Vector2(LivingDoorX(p.Front),Z("family-living").size.y/2-.95f),Vector2.down,p.Front);objectRooms[p.Front]="family-living";objectRooms[p.Back]=p.Room;}
  catalog.portals=links.ToArray();
  foreach(var npc in split.npcs){foreach(var e in npc.schedule){var room=!string.IsNullOrEmpty(e.objectId)&&objectRooms.TryGetValue(e.objectId,out var place)?R(place):catalog.Resolve(e.zone,e.position);if(room!=null){if(e.zone!=room.roomId)e.position-=room.legacyOffset;e.zone=room.roomId;}}var home=catalog.Resolve(npc.homeZone,npc.homePosition);if(home!=null){npc.homeZone=home.roomId;npc.homePosition-=home.legacyOffset;}}
  var doorTemplate=UnityEngine.Object.Instantiate(w.objects.First(o=>o.id=="family-parents-door").gameObject);doorTemplate.name="RoomDoorTemplate";PrefabUtility.SaveAsPrefabAsset(doorTemplate,"Assets/_Game/Prefabs/SceneResidents/DoorTemplate.prefab");UnityEngine.Object.DestroyImmediate(doorTemplate);var sourceScheduler=w.GetComponent<WorldNPCScheduler>();templates=sourceScheduler.actors.Select(a=>{var go=UnityEngine.Object.Instantiate(a.gameObject);go.name=a.npcId;go.transform.position=Vector3.zero;var prefab=PrefabUtility.SaveAsPrefabAsset(go,"Assets/_Game/Prefabs/SceneResidents/"+a.npcId+".prefab");UnityEngine.Object.DestroyImmediate(go);return prefab.GetComponent<WorldInteractable>();}).ToArray();var label=UnityEngine.Object.Instantiate(sourceScheduler.activityLabels[0].gameObject);label.name="SceneNPCActivityLabel";label.transform.position=Vector3.zero;label.SetActive(false);labelTemplate=PrefabUtility.SaveAsPrefabAsset(label,"Assets/_Game/Prefabs/SceneResidents/ActivityLabel.prefab").GetComponent<TMPro.TMP_Text>();UnityEngine.Object.DestroyImmediate(label);
  EditorUtility.SetDirty(split);EditorUtility.SetDirty(catalog);AssetDatabase.SaveAssets();foreach(var room in catalog.rooms)Export(room);EditorUtility.SetDirty(split);FixRoomDining();
  var routes=AssetDatabase.LoadAssetAtPath<SceneCatalog>("Assets/_Game/Data/SceneRoutes.asset");routes.routes=routes.routes.Where(r=>r.id<SceneId.RoomFamilyLiving).Concat(catalog.rooms.Select(r=>new SceneRoute{id=r.sceneId,sceneName=r.sceneName,implemented=true})).ToArray();EditorUtility.SetDirty(routes);EditorBuildSettings.scenes=EditorBuildSettings.scenes.Where(s=>!s.path.StartsWith(Folder)).Concat(catalog.rooms.Select(r=>new EditorBuildSettingsScene(Folder+r.sceneName+".unity",true))).ToArray();
  var bootstrap=EditorSceneManager.OpenScene("Assets/_Game/Scenes/Bootstrap.unity");var context=UnityEngine.Object.FindAnyObjectByType<GameContext>();context.transitions.roomCatalog=catalog;context.game.world.rooms=catalog;EditorUtility.SetDirty(context.transitions);EditorUtility.SetDirty(context.game.world);EditorSceneManager.MarkSceneDirty(bootstrap);EditorSceneManager.SaveScene(bootstrap);AssetDatabase.SaveAssets();RoomVisualSetup.Apply();GrowthVisualSetup.ApplyToRooms();File.WriteAllText("Docs/SceneArchitecture/ROOM_MANIFEST.json",JsonUtility.ToJson(catalog,true));EditorSceneManager.OpenScene(Folder+"FamilyHome_IanBedroom.unity");
 }
 public static void FixRoomDining(){var path=Data+"DiningMaterial.mat";var mat=AssetDatabase.LoadAssetAtPath<Material>(path);if(mat==null){mat=new Material(Material);mat.SetFloat("_Cutoff",.5f);AssetDatabase.CreateAsset(mat,path);}var scene=EditorSceneManager.OpenScene(Folder+"FamilyHome_Kitchen.unity");var table=UnityEngine.Object.FindAnyObjectByType<FamilySharedDiningPresentation>();table.visual.sharedMaterial=mat;EditorSceneManager.MarkSceneDirty(scene);EditorSceneManager.SaveScene(scene);AssetDatabase.SaveAssets();}
 static void Add(string id,string from,string to,Vector2 arrival,Vector2 facing,string reverse)=>links.Add(new RoomPortalDefinition{doorId=id,sourceRoom=from,destinationRoom=to,arrival=arrival,facing=facing,destinationEntryId=reverse+"/arrival"});
 static void Export(RoomSceneDefinition room){var source=EditorSceneManager.OpenScene(Source);string path=Folder+room.sceneName+".unity";EditorSceneManager.SaveScene(source,path,true);var scene=EditorSceneManager.OpenScene(path);var w=UnityEngine.Object.FindAnyObjectByType<LifeWorldController>();var identity=w.gameObject.AddComponent<RoomSceneIdentity>();identity.cameraOffset=room.roomId=="family-living"?Vector2.up:Vector2.zero;identity.roomId=room.roomId;identity.catalog=catalog;identity.rules=split;var scheduler=w.GetComponent<WorldNPCScheduler>();
  foreach(var p in w.GetComponentsInChildren<WorldWorkstationPresentation>(true))p.actor=null;foreach(var actor in scheduler.actors)if(actor!=null)UnityEngine.Object.DestroyImmediate(actor.gameObject);foreach(var label in scheduler.activityLabels)if(label!=null)UnityEngine.Object.DestroyImmediate(label.gameObject);scheduler.actors=Array.Empty<WorldInteractable>();scheduler.activityLabels=Array.Empty<TMPro.TMP_Text>();scheduler.residentPrefabs=templates;scheduler.labelPrefab=labelTemplate;scheduler.sceneScoped=true;
  var keep=w.objects.Where(o=>o!=null&&o.kind!=WorldInteractionKind.NPC&&objectRooms.TryGetValue(o.id,out var owner)&&owner==room.roomId).ToArray();foreach(var o in w.objects.Where(o=>o!=null&&!keep.Contains(o)).ToArray())UnityEngine.Object.DestroyImmediate(o.gameObject);w.objects=keep;foreach(var o in keep)o.zone=room.roomId;
  foreach(Transform child in w.transform.Cast<Transform>().ToArray()){
   if(child==null)continue;var ownedObject=child.GetComponent<WorldInteractable>();if(ownedObject!=null){if(!keep.Contains(ownedObject))UnityEngine.Object.DestroyImmediate(child.gameObject);continue;}if(child==w.furnishingRoot||child==w.audio.effects?.transform||child==w.audio.ambience?.transform)continue;
   bool keepGeometry=room.family?child.name.EndsWith(" / "+FamilyLife.Home):child.name.EndsWith(" / "+room.roomId);
   if(room.roomId=="home"&&(child.name.StartsWith("Visual Rebuild")||child.name.StartsWith("Improved residence")))keepGeometry=true;
   if(room.roomId=="residence"&&child.name=="Resident home interior")keepGeometry=true;
   if(child.GetComponent<WorldStreetLife>()!=null)keepGeometry=room.roomId=="city";
   if(!keepGeometry){bool outside=room.family||!new Rect(Z(room.roomId).origin-Z(room.roomId).size/2,Z(room.roomId).size).Contains(child.position);if(outside||child.position==Vector3.zero)UnityEngine.Object.DestroyImmediate(child.gameObject);}
  }
  foreach(var root in scene.GetRootGameObjects().Where(o=>o.name=="ARCHIVE - 3D Elements (Inactive)"||o.name=="2D Stage").ToArray())UnityEngine.Object.DestroyImmediate(root);
  if(room.family){FamilyShell(w,room);ArrangeResidentialRoom(w,room);}
  if(room.roomId=="alley"){var access=w.gameObject.AddComponent<ResidentialEntrancePresentation>();access.personalEntranceObjects=w.transform.Cast<Transform>().Where(t=>t.name=="house-entrance"||t.name.EndsWith(" / 이안의 집")).Select(t=>t.gameObject).ToArray();}
  foreach(var p in links.Where(p=>p.sourceRoom==room.roomId)){var o=w.objects.FirstOrDefault(o=>o.id==p.doorId);if(o==null&&room.family)o=CreateFamilyDoor(w,p,room);if(o==null)throw new Exception("Missing room portal "+p.doorId);o.targetZone=p.destinationRoom;o.arrival=p.arrival;o.zone=room.roomId;}
  foreach(var p in links.Where(p=>p.destinationRoom==room.roomId)){var go=new GameObject("Entry / "+p.destinationEntryId,typeof(RoomEntryPoint));go.transform.SetParent(w.transform,false);go.transform.position=Z(room.roomId).origin+p.arrival;var point=go.GetComponent<RoomEntryPoint>();point.entryId=p.destinationEntryId;point.doorId=p.destinationEntryId.Replace("/arrival","");point.facing=p.facing;}
  var family=w.GetComponent<FamilyHomeRuntime>();if(family!=null){family.crib=room.roomId=="family-ian-bedroom"?w.objects.First(o=>o.id=="family-bed").transform.Find("Newborn crib").GetComponent<SpriteRenderer>():null;if(!room.family)UnityEngine.Object.DestroyImmediate(family);}
  if(room.roomId!="home"){var starter=w.GetComponent<StarterHomePresentation>();if(starter!=null)UnityEngine.Object.DestroyImmediate(starter);w.upgradedHome=null;w.starterWritingDesk=null;}
  w.lamps=w.lamps.Where(l=>l!=null).ToArray();w.roomBackdrops=w.roomBackdrops.Where(b=>b!=null).ToArray();w.follow.target.transform.position=new Vector3(Z(room.roomId).origin.x,Z(room.roomId).origin.y,-10);w.follow.target.orthographicSize=Z(room.roomId).cameraSize>0?Z(room.roomId).cameraSize:5.8f;w.Player.transform.position=Z(room.roomId).origin+Z(room.roomId).spawn;
  if(w.objects.Any(o=>o.zone!=room.roomId))throw new Exception("Foreign object "+room.roomId);if(scene.GetRootGameObjects().SelectMany(o=>o.GetComponentsInChildren<GameManager>(true)).Any())throw new Exception("Duplicate manager export");EditorSceneManager.MarkSceneDirty(scene);EditorSceneManager.SaveScene(scene);
 }
 static Material Material=>AssetDatabase.LoadAssetAtPath<Material>("Assets/_Game/Art/VisualRebuild/WorldAlphaCut.mat");
 static void FamilyShell(LifeWorldController w,RoomSceneDefinition room){var root=w.transform.Cast<Transform>().FirstOrDefault(t=>t.name.EndsWith(" / "+FamilyLife.Home));if(root==null)throw new Exception("Missing family authored root");foreach(Transform child in root.Cast<Transform>().ToArray()){bool keep=room.roomId=="family-living"&&child.name=="Family TV"||room.roomId=="family-kitchen"&&child.name=="One shared family dining table";if(!keep)UnityEngine.Object.DestroyImmediate(child.gameObject);}root.name=room.sceneName+" / "+room.roomId;var z=Z(room.roomId);var art=AssetDatabase.LoadAllAssetsAtPath("Assets/_Game/Art/VisualRebuild/Architecture.png").OfType<Sprite>().ToDictionary(s=>s.name);
  SpriteRenderer Image(string name,Sprite sprite,Vector2 position,Vector2 size,int order){var go=new GameObject(name,typeof(SpriteRenderer));go.transform.SetParent(root,false);go.transform.position=z.origin+position;var sr=go.GetComponent<SpriteRenderer>();sr.sprite=sprite;sr.sharedMaterial=Material;sr.drawMode=name.EndsWith("visible")?SpriteDrawMode.Sliced:SpriteDrawMode.Tiled;sr.size=size;sr.transform.position=z.origin+position-new Vector2((.5f-sprite.pivot.x/sprite.rect.width)*size.x,(.5f-sprite.pivot.y/sprite.rect.height)*size.y);sr.sortingOrder=order;return sr;}
  void Wall(string name,Vector2 p,Vector2 size){var go=new GameObject(name,typeof(BoxCollider2D));go.transform.SetParent(root,false);go.transform.position=z.origin+p;go.GetComponent<BoxCollider2D>().size=size;if(name.StartsWith("West")||name.StartsWith("East"))Image(name+" visible",art["VerticalWall"],p+Vector2.up*.2f,new Vector2(.22f,size.y+.4f),-3500);else if(name.StartsWith("South"))Image(name+" cutaway",art["CutawayWall"],p,new Vector2(size.x,.3f),1000-Mathf.RoundToInt((z.origin.y+p.y)*100));}
  Image("Room owned floor",art[room.roomId=="family-bathroom"?"JadeFloor":"OakFloor"],Vector2.zero,z.size,-5000);Image("Room owned rear wallpaper",art[room.roomId=="family-bathroom"?"JadeWall":"IvoryWall"],new Vector2(0,z.size.y/2+1.05f),new Vector2(z.size.x,2.3f),-4000);
  Wall("West wall",new Vector2(-z.size.x/2,0),new Vector2(.18f,z.size.y));Wall("East wall",new Vector2(z.size.x/2,0),new Vector2(.18f,z.size.y));
  // Only the living room has north-facing doors; bedroom/kitchen/bath exits face south.
  var gaps=room.roomId=="family-living"?new[]{-3.3f,-1.1f,1.1f,3.3f}:Array.Empty<float>();float left=-z.size.x/2;int part=0;foreach(float gap in gaps){float end=gap-.8f;if(end>left)Wall("North wall "+part++,new Vector2((left+end)/2,z.size.y/2),new Vector2(end-left,.18f));left=gap+.8f;}if(left<z.size.x/2)Wall("North wall "+part,new Vector2((left+z.size.x/2)/2,z.size.y/2),new Vector2(z.size.x/2-left,.18f));
  float southDoor=room.roomId=="family-living"?3.2f:room.roomId=="family-kitchen"?-4f:0;float south=-z.size.y/2;float west=-z.size.x/2,east=z.size.x/2;Wall("South wall left",new Vector2((west+southDoor-.8f)/2,south),new Vector2(southDoor-.8f-west,.18f));Wall("South wall right",new Vector2((southDoor+.8f+east)/2,south),new Vector2(east-southDoor-.8f,.18f));
  foreach(var p in links.Where(p=>p.sourceRoom==room.roomId)){var old=w.objects.FirstOrDefault(o=>o.id==p.doorId);if(old!=null){w.objects=w.objects.Where(o=>o!=old).ToArray();UnityEngine.Object.DestroyImmediate(old.gameObject);}CreateFamilyDoor(w,p,room);}
 }
 static WorldInteractable CreateFamilyDoor(LifeWorldController w,RoomPortalDefinition p,RoomSceneDefinition room){var o=UnityEngine.Object.Instantiate(AssetDatabase.LoadAssetAtPath<WorldInteractable>("Assets/_Game/Prefabs/SceneResidents/DoorTemplate.prefab"),w.transform);o.gameObject.SetActive(true);o.name=o.id=p.doorId;o.title=R(p.destinationRoom)?.title+" 출입";o.zone=room.roomId;o.targetZone=p.destinationRoom;o.arrival=p.arrival;Vector2 plane;bool north=room.roomId=="family-living"&&p.doorId!="family-exit";if(north){float x=LivingDoorX(p.doorId);plane=Z(room.roomId).origin+new Vector2(x,Z(room.roomId).size.y/2);}else plane=Z(room.roomId).origin+new Vector2(room.roomId=="family-living"?3.2f:room.roomId=="family-kitchen"?-4f:0,-Z(room.roomId).size.y/2);
  var door=o.GetComponent<WorldDoor>();door.portal=o;door.world=w;door.normal=north?Vector2.up:Vector2.down;o.UsePoint=-door.normal*.8f;o.transform.position=plane+door.normal*.45f;door.threshold=plane-(Vector2)o.transform.position;door.closedCollider.transform.position=plane;door.leaf.transform.position=o.transform.position+(Vector3)door.style.hingeOffset;door.frame.transform.position=o.transform.position;door.opens=0;door.closes=24;o.visual=door.leaf;w.objects=w.objects.Concat(new[]{o}).ToArray();return o;}
}
